<body>
  <div class="card">
    <h1>
      🧠 Workshop: Build with AI
      <span id="seatCounter">20 seats</span>
    </h1>
    <div class="subhead">
      Secure your spot — just 20 available. Enter your name & email.
    </div>

    <!-- seat meter -->
    <div class="seat-meter">
      <div class="seat-fill" id="seatFill" style="width: 0%;"></div>
    </div>
    <div class="seat-stats">
      <div class="stat-item"><strong id="seatsTaken">0</strong> / 20 taken</div>
      <div class="stat-item"><strong id="seatsLeft">20</strong> seats left</div>
    </div>

    <!-- signup form -->
    <form id="signupForm" novalidate>
      <div class="form-group">
        <label for="nameInput">Full name</label>
        <input type="text" id="nameInput" placeholder="e.g. Ada Lovelace" autocomplete="name" required>
      </div>
      <div class="form-group">
        <label for="emailInput">Email address</label>
        <input type="email" id="emailInput" placeholder="ada@example.com" autocomplete="email" required>
      </div>
      <div class="button-group">
        <button type="submit" class="primary" id="registerBtn">🎟️ Reserve my seat</button>
        <button type="button" class="secondary" id="resetBtn" title="Clear all registrations (demo)">⟲ Reset all</button>
      </div>
    </form>

    <!-- feedback message -->
    <div class="message" id="messageBox">
      ⏳ Fill in the form to grab a seat.
    </div>

    <!-- registered attendees list -->
    <div class="registered-list">
      <h3>
        <span>✓ Registered</span>
        <span class="badge" id="attendeeCountBadge">0</span>
      </h3>
      <div class="attendee-tags" id="attendeeList">
        <span class="empty-note">No one yet — be the first!</span>
      </div>
    </div>
    <div class="footer-note">
      Each signup takes 1 seat · max 20
    </div>
  </div>

  <script>
    (function(){
      const MAX_SEATS = 20;

      // ---------- state ----------
      // attendees: array of { name, email, id (unique) }
      let attendees = [];

      // DOM elements
      const nameInput = document.getElementById('nameInput');
      const emailInput = document.getElementById('emailInput');
      const signupForm = document.getElementById('signupForm');
      const registerBtn = document.getElementById('registerBtn');
      const resetBtn = document.getElementById('resetBtn');
      const messageBox = document.getElementById('messageBox');
      const seatFill = document.getElementById('seatFill');
      const seatsTakenEl = document.getElementById('seatsTaken');
      const seatsLeftEl = document.getElementById('seatsLeft');
      const seatCounter = document.getElementById('seatCounter');
      const attendeeListEl = document.getElementById('attendeeList');
      const attendeeCountBadge = document.getElementById('attendeeCountBadge');

      // ---------- helpers ----------
      function generateId() {
        return Date.now() + '-' + Math.random().toString(36).substring(2, 9);
      }

      // update UI based on attendees array
      function render() {
        const taken = attendees.length;
        const left = MAX_SEATS - taken;

        // update meter
        const percent = (taken / MAX_SEATS) * 100;
        seatFill.style.width = percent + '%';

        // update numbers
        seatsTakenEl.textContent = taken;
        seatsLeftEl.textContent = left;
        seatCounter.textContent = `${left} seat${left !== 1 ? 's' : ''} left`;

        // attendee count badge
        attendeeCountBadge.textContent = taken;

        // enable/disable register button and inputs
        const full = left <= 0;
        registerBtn.disabled = full;
        nameInput.disabled = full;
        emailInput.disabled = full;

        // render attendee list
        attendeeListEl.innerHTML = '';
        if (attendees.length === 0) {
          const emptyNote = document.createElement('span');
          emptyNote.className = 'empty-note';
          emptyNote.textContent = 'No one yet — be the first!';
          attendeeListEl.appendChild(emptyNote);
        } else {
          attendees.forEach(attendee => {
            const tag = document.createElement('span');
            tag.className = 'attendee-tag';
            tag.textContent = attendee.name;

            // small remove button (optional, but we keep it — helps admin remove)
            const removeBtn = document.createElement('button');
            removeBtn.type = 'button';
            removeBtn.className = 'remove-btn';
            removeBtn.innerHTML = '✕';
            removeBtn.setAttribute('aria-label', `Remove ${attendee.name}`);
            removeBtn.addEventListener('click', (e) => {
              e.stopPropagation();
              removeAttendee(attendee.id);
            });

            tag.appendChild(removeBtn);
            attendeeListEl.appendChild(tag);
          });
        }

        // if full, show a persistent message if not overridden by a success/error
        if (full) {
          // if the message box doesn't already have error/success, set a notice
          const currentClass = messageBox.className;
          if (!currentClass.includes('success') && !currentClass.includes('error')) {
            setMessage('🚫 All 20 seats are taken. No more signups.', 'error');
          }
        } else {
          // if message is about full and seats become available (reset), reset to neutral
          if (messageBox.textContent.includes('seats are taken') || messageBox.textContent.includes('Full')) {
            setMessage('⏳ Fill in the form to grab a seat.', '');
          }
        }
      }

      // set message with type: 'error', 'success', or '' (neutral)
      function setMessage(text, type = '') {
        messageBox.textContent = text;
        messageBox.className = 'message'; // reset
        if (type === 'error') messageBox.classList.add('error');
        if (type === 'success') messageBox.classList.add('success');
      }

      // remove attendee by id
      function removeAttendee(id) {
        const index = attendees.findIndex(a => a.id === id);
        if (index !== -1) {
          // if we remove someone and were full, re-enable form
          const removed = attendees.splice(index, 1)[0];
          setMessage(`Removed ${removed.name} from the list.`, '');
          render();
        }
      }

      // validation
      function isValidEmail(email) {
        // simple but effective email regex
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      }

      // handle signup
      function handleSignup(e) {
        e.preventDefault();

        // if full, prevent (just in case)
        if (attendees.length >= MAX_SEATS) {
          setMessage('🚫 All seats are taken. Cannot register more people.', 'error');
          render();
          return;
        }

        const name = nameInput.value.trim();
        const email = emailInput.value.trim();

        // validation
        if (!name) {
          setMessage('⚠️ Please enter your full name.', 'error');
          nameInput.focus();
          return;
        }
        if (name.length < 2) {
          setMessage('⚠️ Name must be at least 2 characters.', 'error');
          nameInput.focus();
          return;
        }
        if (!email) {
          setMessage('⚠️ Please enter your email address.', 'error');
          emailInput.focus();
          return;
        }
        if (!isValidEmail(email)) {
          setMessage('⚠️ Please enter a valid email address (e.g., ada@example.com).', 'error');
          emailInput.focus();
          return;
        }

        // (optional) prevent duplicate email? Not required but nice
        const emailExists = attendees.some(a => a.email.toLowerCase() === email.toLowerCase());
        if (emailExists) {
          setMessage('⚠️ This email is already registered. Each person can only take one seat.', 'error');
          emailInput.focus();
          return;
        }

        // create attendee
        const newAttendee = {
          id: generateId(),
          name: name,
          email: email
        };
        attendees.push(newAttendee);

        // clear inputs
        nameInput.value = '';
        emailInput.value = '';

        // success feedback
        const left = MAX_SEATS - attendees.length;
        setMessage(`✅ Seat reserved for ${name}! ${left} seat${left !== 1 ? 's' : ''} remaining.`, 'success');

        // re-render UI
        render();

        // focus back on name for convenience
        if (attendees.length < MAX_SEATS) {
          nameInput.focus();
        } else {
          registerBtn.disabled = true;
        }
      }

      // reset all attendees (demo / clear)
      function resetAll() {
        if (attendees.length === 0) {
          setMessage('ℹ️ No registrations to reset.', '');
          return;
        }
        attendees = [];
        nameInput.value = '';
        emailInput.value = '';
        setMessage('🔄 All seats are free again. 20 seats available.', '');
        render();
        nameInput.focus();
      }

      // ---------- initial load ----------
      // Preload a couple of sample attendees to demonstrate the meter? 
      // Comment out if you want truly empty. We'll add none for a clean start.
      // But to make the page feel alive, you can uncomment the next lines:
      /*
      attendees.push({ id: generateId(), name: 'Grace Hopper', email: 'grace@navy.mil' });
      attendees.push({ id: generateId(), name: 'Alan Turing', email: 'alan@bletchley.uk' });
      */

      // render initial (0 attendees)
      render();

      // event listeners
      signupForm.addEventListener('submit', handleSignup);
      resetBtn.addEventListener('click', resetAll);

      // if full and someone tries to submit via enter, handleSignup already checks.
      // also keep message if full dynamic via render
    })();
  </script>
</body>
</html>
